mapper.select:
SELECT COUNT(1) FROM dept_work_order
WHERE is_deleted = 0 AND dept_receive_time > #{after}
  AND category = #{category}
AND county_code = #{countyCode}

SELECT COUNT(1) FROM dept_audit_log l
WHERE l.create_time > #{after}
  AND (
        (l.operator IN (SELECT CONCAT(u.user_type, '-', u.job_no) FROM sys_user u
                        WHERE u.is_deleted = 0 AND u.user_type = #{dept}
                          AND (u.region_code = #{countyCode} OR #{countyCode} IS NULL))
         AND NOT (l.module = 'order-receive'))
        OR
        (l.module = 'order-receive'
         AND (l.target_type = #{dept}
              OR l.target_type = CONCAT(#{dept}, ':', #{countyCode})))
      )

SELECT COUNT(1) FROM admin_order_archive
WHERE is_deleted = 0 AND is_archived = 1
  AND archive_time > #{after}
